blocks.code:
/* Apply to everything, including ::before and ::after. */
*,
*::before,
*::after {
  box-sizing: border-box;
}

.hex      { color: #1572b6; }
.rgb      { color: rgb(21, 114, 182); }
.rgba     { color: rgb(21 114 182 / 0.5); }       /* modern slash alpha */
.hsl      { color: hsl(204 79% 40%); }
.oklch    { color: oklch(54% 0.13 245); }         /* perceptually uniform */
.mix      { color: color-mix(in oklch, red, blue 50%); }
.current  { color: crimson; border: 1px solid currentColor; }

body {
  font-family:
    system-ui,                             /* macOS / iOS / Windows 11 */
    -apple-system, "Segoe UI", Roboto,     /* Apple, Windows, Android   */
    "Helvetica Neue", Arial,               /* fallbacks                  */
    sans-serif;                            /* generic                    */
}

code, pre, kbd {
  font-family: ui-monospace, "SF Mono", "Cascadia Code", "JetBrains Mono",
               "Fira Code", Menlo, Consolas, monospace;
}

.banner {
  position: sticky;
  top: 0;
  z-index: 10;
  background: white;
}

.tooltip {
  position: absolute;          /* positioned relative to nearest positioned ancestor */
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
}

.modal-backdrop {
  position: fixed;
  inset: 0;                    /* top/right/bottom/left: 0 */
  background: rgb(0 0 0 / 0.5);
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr));
  gap: 1.5rem;
}
/* As many 18rem-min columns as fit; wider columns fill remaining space. */

/* Base: mobile */
.layout { display: flex; flex-direction: column; }

/* Tablet and up */
@media (min-width: 48em) {
  .layout { flex-direction: row; }
}

/* Desktop and up */
@media (min-width: 64em) {
  .layout { grid-template-columns: 240px 1fr 320px; display: grid; }
}

.button {
  transition: transform 200ms cubic-bezier(0.4, 0, 0.2, 1),
              background-color 200ms ease,
              box-shadow 200ms ease;
}
.button:hover { transform: translateY(-2px); }
.button:active { transform: translateY(0); }
.button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.sidebar { container-type: inline-size; container-name: sidebar; }

@container sidebar (width > 240px) {
  .widget { display: grid; grid-template-columns: 80px 1fr; }
}
@container sidebar (width <= 240px) {
  .widget { display: block; }
}

:root {
  /* Color tokens */
  --color-brand: oklch(60% 0.2 250);
  --color-brand-hover: color-mix(in oklch, var(--color-brand), white 20%);
  --color-bg: white;
  --color-fg: #111;
  --color-border: #e5e7eb;

  /* Spacing scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-4: 1rem;
  --space-8: 2rem;

  /* Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-full: 9999px;
}

/* Show focus ring only for keyboard users */
.button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

/* Remove the default ring for mouse users */
.button:focus:not(:focus-visible) { outline: none; }

/* Highlight a form row when any field inside is focused */
.form-row:focus-within {
  background: #f0f9ff;
}

.img-grayscale { filter: grayscale(1); }
.img-vintage { filter: sepia(0.4) contrast(1.1) saturate(1.3); }
.img-hover { transition: filter 200ms; }
.img-hover:hover { filter: brightness(1.1) saturate(1.2); }

/* drop-shadow follows the alpha shape */
.icon {
  filter: drop-shadow(0 4px 6px rgb(0 0 0 / 0.2));
}

/* Cheap (composite only) */
.move { transform: translateX(10px); opacity: 0.8; }

/* Medium (paint) */
.color { color: red; background: white; box-shadow: 0 0 10px black; }

/* Expensive (layout) */
.layout { width: 50%; margin: 1rem; padding: 1rem; }

/* Bad: removes focus indicator entirely */
a:focus { outline: none; }

/* Good: ring only for keyboard users */
a:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
a:focus:not(:focus-visible) { outline: none; }

@media print {
  /* Hide UI chrome */
  nav, .sidebar, .ads, .footer-nav, .cookie-banner { display: none; }

  /* Expand <details> for print */
  details { display: block; }
  details > summary { list-style: none; }
  details > *:not(summary) { display: block !important; }

  /* Expand main content to full width */
  main { width: 100% !important; margin: 0 !important; }

  /* Black text on white */
  body { background: white; color: black; font-size: 12pt; }

  /* Show full URLs after links */
  a[href^="http://"]::after,
  a[href^="https://"]::after {
    content: " (" attr(href) ")";
    font-size: 0.85em;
    color: #555;
  }

  /* Avoid breaking inside cards/figures */
  figure, .card, table, tr { break-inside: avoid; }

  /* Force a page break before each H1 */
  h1 { break-before: page; }
  h1:first-of-type { break-before: avoid; }
}

@property --gradient-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.spinner {
  background: conic-gradient(from var(--gradient-angle), red, yellow, lime, red);
  animation: spin 2s linear infinite;
}
@keyframes spin {
  to { --gradient-angle: 360deg; }
}
